def solve():
    V, E = map(int, input().split())
    edges = []
    for _ in range(E):
        edges.append(list(map(int, input().split())))
    edges.sort(key=lambda x: x[2])
    parent = list(range(V))
    def find(i):
        if parent[i] == i: return i
        parent[i] = find(parent[i])
        return parent[i]
    def union(i, j):
        r1, r2 = find(i), find(j)
        if r1 != r2:
            parent[r1] = r2
            return True
        return False
    ans = 0
    for u, v, w in edges:
        if union(u, v):
            ans += w
    print(ans)

if __name__ == '__main__':
    solve()
